import{j as e}from"./blog-pages-Cba4hDr6.js";import{P as a}from"./compare-pages-BzMkvKVB.js";import{U as r}from"./UsecaseDeepDive-ByuYVgBP.js";const o=[{factor:"Asset count (typical NPP)",atlantis:"5,000–25,000 safety-related + balance-of-plant components",competitor:"—"},{factor:"Primary failure modes",atlantis:"PWSCC, IGSCC, IASCC, FAC, thermal fatigue, vibration fatigue, irradiation embrittlement",competitor:"—"},{factor:"Code references",atlantis:"ASME Section XI (in-service inspection), ASME B&amp;PV Section III, NRC RG 1.147 / 1.193, EPRI inspection guidelines",competitor:"—"},{factor:"NDT methods deployed",atlantis:"PAUT, EMAT, eddy current (steam generator tubes), MT/PT, surface examination, visual",competitor:"—"},{factor:"Inspection cycle",atlantis:"10-year ISI intervals per ASME XI; refueling outage scope every 18–24 months",competitor:"—"},{factor:"Atlantis ROI typical",atlantis:"Outage scope efficiency + reduced rework + INPO / NRC audit defensibility",competitor:"—"},{factor:"Regulatory alignment",atlantis:"NRC, IAEA, INPO, country-specific regulators (CNSC, ONR, ASN, etc.)",competitor:"—"}],i=[{question:"Can Atlantis Digital Twin be used in a nuclear environment?",answer:"Yes — with appropriate cybersecurity, deployment isolation, and procedural integration. We support air-gapped on-prem deployment for nuclear plants where direct cloud connectivity is not permitted. Cybersecurity follows IEC 62443 and NRC RG 5.71 guidance. The platform itself is not safety-related software (NSSS Class 1E) and does not perform any control function — it is an inspection record and engineering analysis platform that supports the integrity workflow without taking any safety credit."},{question:"How does ASME Section XI inspection cycle alignment work?",answer:"Atlantis aligns to the 10-year ASME XI ISI (in-service inspection) interval with the standard period and program structure. The plant-specific inspection plan loads as the schedule, and individual inspection events on safety-related components import as inspection records with the relevant ASME XI examination category. Refueling outage scope generates from the ISI plan plus emergent items from operating experience review."},{question:"What about steam generator tube inspection?",answer:"Steam generator tube eddy current inspection is supported as a first-class workflow. Tube-by-tube records, signal interpretation history, plugging decisions, sleeve installation history, and trend analysis across multiple outages all live in the asset record. The 3D SG model overlays plugging/sleeve status and indication history. Major eddy current data formats (Eddyfi, Zetec, Olympus) import natively."},{question:"How does FAC (flow-accelerated corrosion) program management work?",answer:"FAC program management per EPRI / CHECWORKS guidelines is supported with FAC-specific component templates, predicted vs measured wear comparison, replacement decision tracking, and CHECWORKS data import. The 3D plant model overlays FAC risk on susceptible piping segments. Outage inspection scope for FAC-affected piping pre-populates from the predictive model and prior inspection history."},{question:"What about regulatory record retention?",answer:"Nuclear inspection records have very long retention requirements (typically plant life + 10 years, sometimes longer for specific record categories). Atlantis retains all inspection records, FFS calculations, and engineering decisions natively for the full retention period. Air-gapped deployments include backup and disaster recovery patterns that meet NRC audit requirements."}];function p(){const n={"@context":"https://schema.org","@graph":[{"@type":"Article",headline:"Atlantis Digital Twin for Nuclear Plants: ASME XI ISI, SG Tubes, FAC [2026]",datePublished:"2026-05-09",dateModified:"2026-05-09",author:{"@type":"Person",name:"Anoop Rayavarapu"},publisher:{"@type":"Organization",name:"Atlantis NDT"},mainEntityOfPage:{"@type":"WebPage","@id":"https://atlantisndt.com/digital-twins/nuclear-plant"}},{"@type":"FAQPage",mainEntity:i.map(t=>({"@type":"Question",name:t.question,acceptedAnswer:{"@type":"Answer",text:t.answer}}))}]};return e.jsx(a,{title:"Atlantis Digital Twin for Nuclear Plants: ASME XI ISI, SG Tubes, FAC [2026]",description:"Nuclear plant digital twin: ASME Section XI ISI cycle, steam generator tube eddy current, FAC program management per EPRI/CHECWORKS, air-gapped on-prem deployment for NRC environments.",canonical:"https://atlantisndt.com/digital-twins/nuclear-plant",eyebrow:"Use Case",h1:"Atlantis Digital Twin for Nuclear Plants: ASME Section XI ISI, SG Tubes, FAC [2026]",intro:"Nuclear plants combine the strictest inspection regime (ASME Section XI), the most consequential failure modes, and the longest record retention requirements. Atlantis Digital Twin runs in air-gapped on-prem deployment with full ISI cycle alignment, SG tube workflow, and FAC program management.",heroGradient:"from-emerald-700 to-green-800",competitorLabel:"Nuclear Specifics",compareRows:o,faqs:i,related:[{href:"/digital-twins/heat-exchanger",title:"Heat Exchanger",blurb:"Steam generator tube inspection workflow detail."},{href:"/digital-twins/pressure-vessel",title:"Pressure Vessel",blurb:"Reactor pressure vessel + safety-related vessel workflow."},{href:"/digital-twins/refinery",title:"Refinery",blurb:"Adjacent process plant integrity workflow."},{href:"/digital-twins",title:"Atlantis Digital Twin",blurb:"Product page — features, pricing, case studies."},{href:"/integrations/sap-pm",title:"SAP PM Integration",blurb:"How Atlantis fits with nuclear plant SAP / Maximo landscape."},{href:"/contact",title:"Book a Nuclear Demo",blurb:"Bring an ISI inspection plan and a sample SG tube data file. We&rsquo;ll show your plant as a twin in 30 minutes."}],ctaTitle:"See Your Plant as a Live ISI Twin",ctaSubtitle:"Air-gapped deployment, ASME Section XI alignment, and the full SG tube + FAC workflow. Bring a sample data set, leave with a working twin demo.",structuredData:n,bodyChildren:e.jsxs(e.Fragment,{children:[e.jsx("h2",{children:"Nuclear inspection integrity is its own world"}),e.jsx("p",{children:"Nuclear plant integrity differs from oil & gas integrity in three structural ways. (1) The inspection regime is fully prescribed by ASME Section XI with regulatory enforcement (NRC, IAEA, country-specific regulators), so the workflow must align to the prescribed examination categories, frequencies, and acceptance criteria — not to RBI-derived intervals. (2) The damage mechanisms are nuclear-specific (PWSCC, IGSCC, IASCC, irradiation embrittlement, FAC) and the inspection technologies are calibrated for them (PAUT and EMAT for primary system welds, eddy current bobbin and array probes for SG tubes). (3) The cybersecurity, deployment, and record retention requirements are the strictest in industrial software — air-gapped on-prem deployment is normal, not exceptional, and record retention runs to plant life + 10 years."}),e.jsx("h2",{children:"What Atlantis Digital Twin does for a nuclear plant"}),e.jsx("h3",{children:"ASME Section XI ISI alignment"}),e.jsx("p",{children:"The plant-specific 10-year ISI program loads as the schedule, with the standard ASME XI period structure (1st, 2nd, 3rd, 4th period) and examination category alignment (Cat. B-A through F-A). Individual inspection events on safety-related components import as inspection records with the relevant examination category, examination volume, and acceptance criteria. Each refueling outage’s scope generates from the ISI plan plus emergent items from operating experience review."}),e.jsx("h3",{children:"Steam generator tube workflow"}),e.jsx("p",{children:"SG tube eddy current inspection is one of the highest-data-volume workflows in any plant — thousands of tubes per SG, multiple probe types per tube, multi-outage trending. Atlantis stores tube-by-tube records, signal interpretation history, plugging decisions, sleeve installation history, and trend analysis across outages. The 3D SG model overlays plugging/sleeve status and indication history. Major eddy current data formats (Eddyfi, Zetec, Olympus) import natively."}),e.jsx("h3",{children:"FAC program management"}),e.jsx("p",{children:"Flow-accelerated corrosion is one of the most consequential failure modes in BOP piping (Mihama-3 in 2004 was the wake-up call). Atlantis supports FAC program management per EPRI / CHECWORKS guidelines with FAC-specific component templates, predicted vs measured wear comparison, replacement decision tracking, and CHECWORKS data import. The 3D plant model overlays FAC risk on susceptible piping segments. Outage inspection scope for FAC-affected piping pre-populates from the predictive model and prior inspection history."}),e.jsx("h3",{children:"Reactor coolant system integrity"}),e.jsx("p",{children:"Primary system weld inspections per ASME XI Category B-F (RPV welds) and B-J (piping welds), pressurizer and surge line inspection, control rod drive penetration inspection — all live in the asset record with PAUT scan archive, EMAT data, and historical indication tracking. PWSCC and IGSCC susceptible locations get specific damage mechanism templates per EPRI MRP and BWRVIP guidelines."}),e.jsx("h2",{children:"Cybersecurity and deployment"}),e.jsx("p",{children:"Air-gapped on-prem deployment is the norm. Atlantis runs on customer-managed infrastructure with no outbound connectivity required. IEC 62443 and NRC RG 5.71 alignment for the cybersecurity controls. The software itself is not safety-related (not Class 1E) and performs no control function — it is an inspection record and engineering analysis platform supporting the integrity workflow without taking any safety credit. This positioning keeps the licensing and qualification footprint manageable while delivering the full integrity workflow value."}),e.jsx("h2",{children:"Record retention"}),e.jsx("p",{children:"Nuclear inspection records run to plant life + 10 years for most categories, longer for some. Atlantis retains all inspection records, FFS calculations, and engineering decisions natively for the full retention period. Air-gapped deployments include backup and disaster recovery patterns that meet NRC audit requirements. Record export to long-term archive formats (PDF/A, structured XML) is supported for the very long retention horizons."}),e.jsx("h2",{children:"ROI in nuclear"}),e.jsx("p",{children:"Nuclear ROI calculation differs from oil & gas. The biggest values are: (1) outage scope efficiency — better-prepared inspection plans reduce critical-path outage time, and an outage day is worth $1M–$3M+ in revenue; (2) reduced rework — better data quality on the first inspection avoids the dispute-and-re-inspect cycle that consumes outage time; (3) audit and INPO defensibility — a structured, queryable integrity record dramatically reduces audit response time and audit findings. Specific dollar ROI varies by plant but the structural value is clear: the platform pays for itself in one good outage cycle."}),e.jsx(r,{slug:"nuclear-plant"})]})})}export{p as default};
